using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace AsterHand {
    internal sealed class DeviceHub : IDisposable {
        readonly Vault vault;readonly ToolHost tools;readonly object gate=new object();
        readonly Dictionary<string,Dictionary<string,object>> incoming=new Dictionary<string,Dictionary<string,object>>(),outgoing=new Dictionary<string,Dictionary<string,object>>();
        readonly Dictionary<string,double> replay=new Dictionary<string,double>();readonly Dictionary<string,List<CancellationTokenSource>> active=new Dictionary<string,List<CancellationTokenSource>>();
        readonly CancellationTokenSource stop=new CancellationTokenSource();readonly SemaphoreSlim clients=new SemaphoreSlim(12);TcpListener listener;
        string code="";double codeExpires;
        public int Port;public string Error="";public bool UiActive=true;
        public event Action Changed;
        public Action RequireAccess {get;set;}
        public DeviceHub(Vault v,ToolHost t,int port=18769,bool listen=true) {vault=v;tools=t;Port=port;if(listen)try{listener=new TcpListener(IPAddress.Any,port);listener.Start(12);Port=((IPEndPoint)listener.LocalEndpoint).Port;Accept();}catch(SocketException){Error="控制端口已被占用，请先退出旧版控制中心，再点击重启服务。";} }
        void Notify() {var e=Changed;if(e!=null)e();}
        public bool Available {get{return !stop.IsCancellationRequested&&(J.Bool(vault.State,"background",true)||UiActive);}}
        public string[] Addresses {get{return NetworkInterface.GetAllNetworkInterfaces().Where(x=>x.OperationalStatus==OperationalStatus.Up&&x.NetworkInterfaceType!=NetworkInterfaceType.Loopback).SelectMany(x=>x.GetIPProperties().UnicastAddresses).Where(x=>x.Address.AddressFamily==AddressFamily.InterNetwork&&!x.Address.ToString().StartsWith("169.254.")).Select(x=>x.Address.ToString()).Distinct().ToArray();}}
        public Dictionary<string,object> Identity() {lock(gate){string pub=J.Str(J.Get(vault.State,"identity"),"public_key");bool fixedCode=J.Str(vault.State,"pair_code_mode")=="fixed";string c=J.Str(vault.State,"pair_code_fixed");if(fixedCode&&c.Length==6)code=c;else if(J.Now>codeExpires||code.Length==0){code=(BitConverter.ToUInt32(Wire.Random(4),0)%1000000).ToString("D6");codeExpires=J.Now+120;}return J.Obj("device_id",Wire.Hex(Wire.Hash(Wire.Decode(pub))),"public_key",pub,"name",J.Str(vault.State,"name"),"pairing",2,"port",Port,"pair_code",code,"pair_code_fixed",fixedCode);}}
        public Dictionary<string,object> Info() {return J.Obj("name",J.Str(vault.State,"name"),"platform","win32","port",Port,"enabled",J.Bool(vault.State,"enabled"),"background",J.Bool(vault.State,"background",true),"available",Available,"addresses",Addresses,"identity",Identity(),"device_id",J.Str(Identity(),"device_id"),"public_key",J.Str(Identity(),"public_key"),"peers",vault.Peers.Select(PublicPeer).ToArray(),"pending",Pending(),"error",Error);}
        static object PublicPeer(object p) {return J.Obj("id",J.Str(p,"id"),"name",J.Str(p,"name"),"host",J.Str(p,"host"),"port",J.Num(p,"port"),"device_id",J.Str(p,"device_id"),"mode",J.Str(p,"mode"),"incoming",J.Bool(p,"incoming",true));}
        public object Peer(string id) {var p=vault.Peers.FirstOrDefault(x=>J.Str(x,"id")==id);if(p==null||string.IsNullOrEmpty(J.Str(p,"host")))throw new Exception("请选择已配对的设备");return p;}
        static string Address(string host,int port,string path) {IPAddress ip;if(!IPAddress.TryParse(host,out ip)||port<1||port>65535)throw new Exception("请输入有效的 IP 和端口");return "http://"+(ip.AddressFamily==AddressFamily.InterNetworkV6?"["+host+"]":host)+":"+port+path;}
        public async Task<Dictionary<string,object>> DeviceAt(string host,int port,CancellationToken ct) {var info=await Net.Json(Address(host,port,"/info"),null,ct,3).ConfigureAwait(false);if(J.Num(info,"agentgo")!=1||J.Num(info,"pairing")!=2)throw new Exception("不是支持配对的 AsterHand 设备");byte[] pub=Wire.Decode(J.Str(info,"public_key"));if(pub.Length!=65||Wire.Hex(Wire.Hash(pub))!=J.Str(info,"device_id"))throw new Exception("设备身份无效");info["host"]=host;info["port"]=port;return info;}
        public async Task<List<object>> Discover(CancellationToken ct) {var targets=new HashSet<string>(vault.Peers.Select(x=>J.Str(x,"host")).Where(x=>x.Length>0));foreach(string address in Addresses){string[] p=address.Split('.');string prefix=string.Join(".",p.Take(3))+".";for(int i=1;i<255;i++)if(prefix+i!=address)targets.Add(prefix+i);}if(targets.Count>1024)throw new Exception("网络范围过大，请使用 IP 连接");var found=new List<object>();var sem=new SemaphoreSlim(32);await Task.WhenAll(targets.Select(async host=>{await sem.WaitAsync(ct).ConfigureAwait(false);try{ct.ThrowIfCancellationRequested();using(var socket=new TcpClient()){var connect=socket.ConnectAsync(host,18769);var done=await Task.WhenAny(connect,Task.Delay(350,ct)).ConfigureAwait(false);if(done!=connect)return;await connect.ConfigureAwait(false);}var info=await DeviceAt(host,18769,ct).ConfigureAwait(false);if(J.Str(info,"device_id")!=J.Str(Identity(),"device_id"))lock(found)found.Add(info);}catch(OperationCanceledException){throw;}catch{}finally{sem.Release();}})).ConfigureAwait(false);return found.GroupBy(x=>J.Str(x,"device_id")).Select(x=>x.First()).ToList();}
        public async Task<object> Begin(object remote,CancellationToken ct) {var local=Identity();if(J.Str(remote,"device_id")==J.Str(local,"device_id"))throw new Exception("不能连接本机");string id=J.Id(),key=Wire.PairKey(J.Get(vault.State,"identity"),remote,id);lock(gate)outgoing[id]=J.Obj("id",id,"key",key,"remote",remote,"created",J.Now);return await Poll(id,true,ct).ConfigureAwait(false);}
        public async Task<object> Poll(string id,bool first,CancellationToken ct) {Dictionary<string,object> r;lock(gate){if(!outgoing.TryGetValue(id,out r)||J.Now-J.Num(r,"created")>120)throw new Exception("连接申请已过期");}var remote=J.Get(r,"remote");string key=J.Str(r,"key"),nonce=J.Id();var packet=Wire.Seal(id,key,J.Obj("id",nonce,"ts",J.Now,"method",first?"pair.request":"pair.status","args",J.Obj("receiver_id",J.Str(remote,"device_id"),"name",J.Str(vault.State,"name"),"port",Port)),"req");var response=await Net.Json(Address(J.Str(remote,"host"),(int)J.Num(remote,"port"),"/pair"),J.Obj("v",2,"request",id,"identity",Identity(),"packet",packet),ct,8).ConfigureAwait(false);var opened=Wire.Open(response,key,"res");var result=J.Get(opened,"result");if(J.Str(response,"pair")!=id||J.Str(opened,"id")!=nonce||J.Str(J.Get(result,"receiver"),"device_id")!=J.Str(remote,"device_id"))throw new Exception("配对响应身份不匹配");string status=J.Str(result,"status");if(status=="accepted"){lock(vault.Sync){var peers=vault.Peers.Where(x=>J.Str(x,"device_id")!=J.Str(remote,"device_id")||J.Bool(x,"incoming",true)).ToList();peers.Add(J.Obj("id",id,"key",key,"name",J.Str(remote,"name"),"host",J.Str(remote,"host"),"port",J.Num(remote,"port"),"device_id",J.Str(remote,"device_id"),"public_key",J.Str(remote,"public_key"),"mode",J.Str(result,"mode"),"incoming",false));vault.SetPeers(peers);}lock(gate)outgoing.Remove(id);Notify();}else if(status=="denied")lock(gate)outgoing.Remove(id);return J.Obj("id",id,"status",status,"mode",J.Str(result,"mode"),"code",Confirmation(key),"device_id",J.Str(remote,"device_id"));}
        static string Confirmation(string key) {return (Convert.ToUInt32(key.Substring(0,8),16)%1000000).ToString("D6");}
        public object[] Pending() {lock(gate){foreach(string id in incoming.Keys.Where(id=>J.Now-J.Num(incoming[id],"created")>120).ToArray())incoming.Remove(id);return incoming.Values.Where(x=>J.Str(x,"status")=="pending").Select(PublicRequest).ToArray();}}
        static object PublicRequest(object r) {return J.Obj("id",J.Str(r,"id"),"name",J.Str(r,"name"),"device_id",J.Str(r,"device_id"),"code",J.Str(r,"code"),"status",J.Str(r,"status"),"created",J.Num(r,"created"));}
        object Pair(object body,string address) {lock(gate){Pending();if(J.Num(body,"v")!=2)throw new Exception("Invalid pairing version");string id=J.Str(body,"request"),key=Wire.PairKey(J.Get(vault.State,"identity"),J.Get(body,"identity"),id);var packet=J.Get(body,"packet");var payload=Wire.Open(packet,key,"req");string method=J.Str(payload,"method");var args=J.Get(payload,"args");if(J.Str(packet,"pair")!=id||J.Str(args,"receiver_id")!=J.Str(Identity(),"device_id")||method!="pair.request"&&method!="pair.status")throw new Exception("Pairing identity mismatch");Dictionary<string,object> r;if(!incoming.TryGetValue(id,out r)){if(method!="pair.request"||incoming.Count>=64||Pending().Length>=8||J.Str(args,"name").Length==0||J.Str(args,"name").Length>80||J.Num(args,"port")<1||J.Num(args,"port")>65535)throw new Exception("Invalid pairing request");r=J.Obj("id",id,"key",key,"host",address,"port",J.Num(args,"port"),"name",J.Str(args,"name"),"device_id",J.Str(J.Get(body,"identity"),"device_id"),"public_key",J.Str(J.Get(body,"identity"),"public_key"),"status","pending","code",Confirmation(key),"created",J.Now);incoming[id]=r;string trust=J.Str(J.Get(J.Get(vault.State,"trust"),J.Str(r,"device_id")),"mode");if(trust=="always"||trust=="deny")Decide(id,trust);Notify();}else if(J.Str(r,"key")!=key||J.Str(r,"device_id")!=J.Str(J.Get(body,"identity"),"device_id"))throw new Exception("Pairing request mismatch");var result=J.Map(PublicRequest(r));result["mode"]=J.Str(r,"mode");result["receiver"]=Identity();return Wire.Seal(id,key,J.Obj("id",J.Str(payload,"id"),"ts",J.Now,"result",result),"res");}}
        public void Decide(string id,string mode) {lock(gate){Dictionary<string,object> r;if(!incoming.TryGetValue(id,out r)||J.Str(r,"status")!="pending"||J.Now-J.Num(r,"created")>120||!new[]{"once","always","deny"}.Contains(mode))throw new Exception("申请已过期");r["status"]=mode=="deny"?"denied":"accepted";r["mode"]=mode;var trust=J.Map(J.Get(vault.State,"trust"));trust[J.Str(r,"device_id")]=J.Obj("name",J.Str(r,"name"),"public_key",J.Str(r,"public_key"),"mode",mode=="once"?"ask":mode);vault.State["trust"]=trust;if(mode!="deny"){var peers=vault.Peers;foreach(var p in peers.Where(x=>J.Str(x,"device_id")==J.Str(r,"device_id")&&J.Bool(x,"incoming",true)).ToArray()){Revoke(J.Str(p,"id"));peers.Remove(p);}peers.Add(J.Obj("id",id,"key",J.Str(r,"key"),"name",J.Str(r,"name"),"host",J.Str(r,"host"),"port",J.Num(r,"port"),"device_id",J.Str(r,"device_id"),"public_key",J.Str(r,"public_key"),"mode",mode,"incoming",true,"expires_at",mode=="once"?J.Now+600:0));vault.SetPeers(peers);vault.State["enabled"]=true;}vault.Save();Notify();}}
        public void Trust(string device,string mode) {if(!new[]{"ask","always","deny"}.Contains(mode))throw new Exception("Invalid trust mode");lock(gate){var trust=J.Map(J.Get(vault.State,"trust"));var previous=J.Map(J.Get(trust,device));previous["mode"]=mode;trust[device]=previous;vault.State["trust"]=trust;foreach(var p in vault.Peers.Where(x=>J.Str(x,"device_id")==device&&J.Bool(x,"incoming",true)).ToArray()){if(mode!="always")Revoke(J.Str(p,"id"));else {J.Map(p)["mode"]="always";J.Map(p)["expires_at"]=0;}}vault.Save();Notify();}}
        public void Revoke(string id) {lock(gate){List<CancellationTokenSource> a;if(active.TryGetValue(id,out a))foreach(var c in a.ToArray())c.Cancel();tools.CloseOwner(id);vault.SetPeers(vault.Peers.Where(x=>J.Str(x,"id")!=id));Notify();}}
        public void Suspend() {lock(gate){foreach(var a in active.Values)foreach(var c in a.ToArray())c.Cancel();foreach(var p in vault.Peers)tools.CloseOwner(J.Str(p,"id"));}}
        public async Task<object> Request(string id,string method,object args,CancellationToken ct) {if(method!="info"&&method!="presence"&&method!="session.close"&&RequireAccess!=null)RequireAccess();var peer=Peer(id);if(method=="info"){args=J.Map(args);J.Map(args)["identity"]=Identity();}string nonce=J.Id();var packet=Wire.Seal(id,J.Str(peer,"key"),J.Obj("id",nonce,"ts",J.Now,"method",method,"args",args),"req");var response=await Net.Json(Address(J.Str(peer,"host"),(int)J.Num(peer,"port"),"/rpc"),packet,ct,130).ConfigureAwait(false);var opened=Wire.Open(response,J.Str(peer,"key"),"res");if(J.Str(response,"pair")!=id||J.Str(opened,"id")!=nonce)throw new Exception("Response identity mismatch");var result=J.Get(opened,"result");if(method=="info"&&J.Str(peer,"device_id").Length>0&&J.Str(result,"device_id").Length>0&&J.Str(peer,"device_id")!=J.Str(result,"device_id"))throw new Exception("Device identity changed");if(J.Str(result,"error").Length>0)throw new Exception(J.Str(result,"error"));return result;}
        public async Task Stream(string id,Action<byte[]> frame,CancellationToken ct) {if(RequireAccess!=null)RequireAccess();var peer=Peer(id);string nonce=J.Id();var packet=Wire.Seal(id,J.Str(peer,"key"),J.Obj("id",nonce,"ts",J.Now,"method","stream2","args",J.Obj("fps",15)),"req");using(var client=Net.Client(86400))using(var req=new System.Net.Http.HttpRequestMessage(System.Net.Http.HttpMethod.Post,Address(J.Str(peer,"host"),(int)J.Num(peer,"port"),"/rpc"))){req.Content=new System.Net.Http.StringContent(J.Write(packet),Encoding.UTF8,"application/json");using(var response=await client.SendAsync(req,System.Net.Http.HttpCompletionOption.ResponseHeadersRead,ct).ConfigureAwait(false)){response.EnsureSuccessStatusCode();using(var stream=await response.Content.ReadAsStreamAsync().ConfigureAwait(false)){uint sequence=0;while(!ct.IsCancellationRequested){byte[] size=await ReadExact(stream,4,ct).ConfigureAwait(false);uint n=Wire.Get(size,0);if(n<80||n>Wire.Limit)throw new Exception("Invalid video frame");var data=await ReadExact(stream,(int)n,ct).ConfigureAwait(false);frame(Wire.OpenFrame(J.Str(peer,"key"),nonce,data,ref sequence));}}}}}
        internal static async Task<byte[]> ReadExact(Stream stream,int count,CancellationToken ct) {var b=new byte[count];int pos=0;while(pos<count){int n=await stream.ReadAsync(b,pos,count-pos,ct).ConfigureAwait(false);if(n==0)throw new EndOfStreamException("Connection ended");pos+=n;}return b;}
        async void Accept() {try{while(!stop.IsCancellationRequested){var tcp=await listener.AcceptTcpClientAsync().ConfigureAwait(false);if(!clients.Wait(0)){tcp.Close();continue;}ServeClient(tcp);}}catch(ObjectDisposedException){}catch(SocketException){}}
        async void ServeClient(TcpClient tcp) {try{await Serve(tcp).ConfigureAwait(false);}catch{}finally{clients.Release();}}
        async Task Serve(TcpClient tcp) {using(tcp)using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(10000);try{tcp.NoDelay=true;var stream=tcp.GetStream();var header=new List<byte>();while(header.Count<16384){var b=await ReadExact(stream,1,timeout.Token).ConfigureAwait(false);header.Add(b[0]);int n=header.Count;if(n>=4&&header[n-4]==13&&header[n-3]==10&&header[n-2]==13&&header[n-1]==10)break;}if(header.Count>=16384)throw new Exception("Headers too large");var lines=Encoding.ASCII.GetString(header.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);var request=lines[0].Split(' ');if(request.Length!=3)throw new Exception("Invalid HTTP");var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in lines.Skip(1).Where(x=>x.Length>0)){int i=line.IndexOf(':');if(i<1||headers.ContainsKey(line.Substring(0,i)))throw new Exception("Invalid headers");headers[line.Substring(0,i)]=line.Substring(i+1).Trim();}string length;int size=0;if(headers.ContainsKey("Transfer-Encoding")||headers.ContainsKey("Origin"))throw new Exception("Forbidden browser request");if(headers.TryGetValue("Content-Length",out length)&&(!int.TryParse(length,out size)||size<0||size>Wire.Limit))throw new Exception("Invalid body length");if(request[0]=="GET"&&request[1]=="/info"){var info=Identity();info["agentgo"]=1;info["platform"]="win32";info["enabled"]=J.Bool(vault.State,"enabled");info["available"]=Available;await Reply(stream,200,info,timeout.Token).ConfigureAwait(false);return;}if(request[0]!="POST"||!Available||size==0)throw new Exception("Unavailable");var body=J.Read(Encoding.UTF8.GetString(await ReadExact(stream,size,timeout.Token).ConfigureAwait(false)));if(request[1]=="/pair"){await Reply(stream,200,Pair(body,((IPEndPoint)tcp.Client.RemoteEndPoint).Address.ToString()),timeout.Token).ConfigureAwait(false);return;}if(request[1]!="/rpc"||!J.Bool(vault.State,"enabled"))throw new Exception("Remote control disabled");string id=J.Str(body,"pair");var peer=Peer(id);if(!J.Bool(peer,"incoming",true))throw new Exception("Not an incoming grant");if(J.Str(peer,"mode")=="once"&&J.Num(peer,"expires_at")<J.Now){Revoke(id);throw new Exception("Session expired");}var payload=Wire.Open(body,J.Str(peer,"key"),"req");lock(gate){foreach(string k in replay.Keys.Where(k=>J.Now-replay[k]>180).ToArray())replay.Remove(k);string key=id+":"+J.Str(payload,"id");if(replay.ContainsKey(key)||replay.Count>=4096)throw new Exception("Replay or busy");replay[key]=J.Now;}
                timeout.CancelAfter(Timeout.Infinite);using(var operation=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){lock(gate){if(!active.ContainsKey(id))active[id]=new List<CancellationTokenSource>();active[id].Add(operation);}try{string method=J.Str(payload,"method");var args=J.Get(payload,"args");if(J.Str(peer,"mode")=="once"){J.Map(peer)["expires_at"]=J.Now+600;vault.Save();}if(method=="stream2"){if(RequireAccess!=null)RequireAccess();if(!J.Bool(vault.State,"screenEnabled"))throw new Exception("Screen access disabled");await Bytes(stream,"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n",operation.Token).ConfigureAwait(false);uint seq=0;while(J.Bool(vault.State,"enabled")&&J.Bool(vault.State,"screenEnabled")&&Available&&!operation.IsCancellationRequested){if(RequireAccess!=null)RequireAccess();var image=WindowsScreen.Capture();var frame=Wire.Frame(J.Str(peer,"key"),J.Str(payload,"id"),++seq,Wire.Decode(J.Str(image,"image_base64")),(int)J.Num(image,"width"),(int)J.Num(image,"height"));var prefix=new byte[4];Wire.Put(prefix,0,(uint)frame.Length);await stream.WriteAsync(prefix,0,4,operation.Token).ConfigureAwait(false);await stream.WriteAsync(frame,0,frame.Length,operation.Token).ConfigureAwait(false);await Task.Delay(66,operation.Token).ConfigureAwait(false);}return;}object result;try{if(method=="info")result=Info();else if(method=="presence")result=J.Obj("ok",true);else if(method=="session.close")result=J.Obj("closed",true);else if(method.StartsWith("terminal."))result=tools.Terminal(method.Substring(9),args,id);else if(method=="execute")result=await tools.Execute(J.Str(args,"tool"),J.Get(args,"arguments"),operation.Token,true).ConfigureAwait(false);else throw new Exception("Unknown method");}catch(Exception e){result=J.Obj("error",J.Error(e));}operation.Token.ThrowIfCancellationRequested();if(!J.Bool(vault.State,"enabled")||!Available)throw new Exception("Revoked");await Reply(stream,200,Wire.Seal(id,J.Str(peer,"key"),J.Obj("id",J.Str(payload,"id"),"ts",J.Now,"result",result),"res"),operation.Token).ConfigureAwait(false);if(method=="session.close"&&J.Str(peer,"mode")=="once")Revoke(id);}finally{lock(gate){active[id].Remove(operation);if(active[id].Count==0)active.Remove(id);}}}
            }catch{try{Reply(tcp.GetStream(),403,J.Obj("error","refused"),stop.Token).GetAwaiter().GetResult();}catch{}}}}
        static Task Bytes(Stream stream,string text,CancellationToken ct) {var b=Encoding.ASCII.GetBytes(text);return stream.WriteAsync(b,0,b.Length,ct);}
        static async Task Reply(Stream stream,int code,object body,CancellationToken ct) {var b=Wire.Utf8(J.Write(body));await Bytes(stream,"HTTP/1.1 "+code+(code==200?" OK":" Forbidden")+"\r\nContent-Type: application/json\r\nContent-Length: "+b.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n",ct).ConfigureAwait(false);await stream.WriteAsync(b,0,b.Length,ct).ConfigureAwait(false);}
        public void Dispose() {Suspend();stop.Cancel();if(listener!=null)listener.Stop();}
    }
}
